#!/bin/bash
SSH="ssh -i $HOME/.ssh/keplerops-foothold -o BatchMode=yes -o StrictHostKeyChecking=accept-new -o ConnectTimeout=8 rowan-dev"
$SSH 'echo "== home"; ls -la /home; echo "== passwd"; grep -v nologin /etc/passwd; echo "== group"; getent group | grep -E "sudo|fieldkest|ot|operator|admin"; echo "== sshd config"; grep -rE "AllowUsers|AuthorizedKeys|Match|PasswordAuth" /etc/ssh/sshd_config /etc/ssh/sshd_config.d 2>/dev/null | head -20; echo "== authorized_keys paths"; ls -la /run/fieldkest-auth; echo "== ps"; ps aux | head -30; echo "== proc cmdlines"; for p in /proc/[0-9]*; do c=$(tr "\0" " " < $p/cmdline 2>/dev/null); [ -n "$c" ] && echo "$p $c"; done | grep -vE "kworker|migration|watchdog|rcu_|ksoftirq|kdevtmpfs|netns|kauditd|khungtask|writeback|kcompactd|ksmd|kthreadd" | head -30' 2>&1 | tail -80
